'use strict';

const fs = require('fs');
const path = require('path');

// Generated by frontend/scripts/gen-company-question-lists.mjs: each guide's reported-question ids, whether the one
// free unlock may open them and their practice task. The question text is not in it.
const DATA_PATH = path.resolve(__dirname, '../../cdn/questions/company-question-lists.json');

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

let cache = null;

/** The question lists by company, or null when the file cannot be read: an unlock is then refused, not guessed. */
function loadQuestionLists(filePath = DATA_PATH) {
  let signature;
  try {
    const stats = fs.statSync(filePath);
    signature = `${filePath}:${stats.size}:${stats.mtimeMs}`;
  } catch {
    return null;
  }
  if (cache?.signature === signature) return cache.lists;
  const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
  const lists = new Map();
  for (const [company, list] of Object.entries(data.companies || {})) {
    lists.set(company, new Map((list.questions || []).map((question) => [question.id, question])));
  }
  cache = { signature, lists };
  return lists;
}

/** The practice task's id from its route, "/react/coding/react-x" -> "react-x", as the catalog names it. */
function practiceIdOf(question) {
  const route = typeof question?.practice?.route === 'string' ? question.practice.route : '';
  return route.split('/').filter(Boolean).pop() || null;
}

/**
 * Checks a request to spend the free unlock: a known company and question that the unlock may open (a locked row
 * with a practice task or an answer guide). Returns the unlock to store or an error with its HTTP status.
 */
function parseFreeUnlock(body, lists, now = new Date()) {
  const company = typeof body?.company === 'string' ? body.company.trim() : '';
  const questionId = typeof body?.questionId === 'string' ? body.questionId.trim() : '';
  if (!SLUG.test(company) || !SLUG.test(questionId)) {
    return { status: 400, code: 'FREE_UNLOCK_INVALID', error: 'company and questionId are required.' };
  }
  if (!lists) return { status: 503, code: 'FREE_UNLOCK_UNAVAILABLE', error: 'Free unlocks are unavailable right now.' };
  const question = lists.get(company)?.get(questionId);
  if (!question) return { status: 404, code: 'FREE_UNLOCK_UNKNOWN', error: 'No such reported question.' };
  if (!question.unlockable) {
    return { status: 400, code: 'FREE_UNLOCK_NOT_ELIGIBLE', error: 'This question has no practice task or answer guide to open.' };
  }
  return { value: { company, questionId, practiceId: practiceIdOf(question), unlockedAt: now } };
}

/** Whether a stored unlock is the one being asked for again. */
function sameUnlock(stored, requested) {
  return Boolean(stored) && stored.company === requested.company && stored.questionId === requested.questionId;
}

module.exports = { loadQuestionLists, parseFreeUnlock, practiceIdOf, sameUnlock };
